/**
 * Bundled game data (generated by /scripts, version-controlled JSON) and lookups.
 * Map tiles are lazy-loaded separately (see src/map/tiles.ts).
 */
import countriesJson from './countries.json';
import citiesJson from './cities.json';
import { buildNameIndex, type NameIndex } from '../game/matching';
import type { City, Country, Target } from '../game/types';

export const COUNTRIES: Country[] = countriesJson as unknown as Country[];
export const CITIES: City[] = citiesJson as unknown as City[];

export const countryById = new Map(COUNTRIES.map((c) => [c.id, c]));
export const cityById = new Map(CITIES.map((c) => [c.id, c]));

export { CONTINENTS } from './continents';

export const TARGETS: Target[] = CITIES.map((c) => {
  const country = countryById.get(c.country)!;
  return {
    id: c.id,
    name: c.name,
    altNames: c.altNames,
    rank: c.rank,
    qualifier: country.name,
    continent: country.continents[0],
  };
});

let index: NameIndex | null = null;
export function nameIndex(): NameIndex {
  return (index ??= buildNameIndex(TARGETS));
}

export const countryOfCity = (id: string): Country | undefined => {
  const city = cityById.get(id);
  return city ? countryById.get(city.country) : undefined;
};

export const cityName = (id: string) => cityById.get(id)?.name ?? id;
